import{c as a,Q as e,j as l,m as s}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"GetBlockIdx","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetBlockIdx","slug":"getblockidx"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/系统变量访问/GetBlockIdx.md","filePath":"api/SIMD-API/基础API/系统变量访问/GetBlockIdx.md"}'),n={name:"api/SIMD-API/基础API/系统变量访问/GetBlockIdx.md"};function o(d,t,i,r,c,p){return e(),l("div",null,[...t[0]||(t[0]=[s(`<h1 id="getblockidx" tabindex="-1">GetBlockIdx <a class="header-anchor" href="#getblockidx" aria-label="Permalink to &quot;GetBlockIdx&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>获取当前核的index，用于代码内部的多核逻辑控制及多核偏移量计算等。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline int64_t GetBlockIdx()</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p>无</p><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><ul><li>GetBlockIdx返回当前核的索引，index的范围为[0, numBlocks)。numBlocks由用户使用&lt;&lt;&lt;&gt;&gt;&gt;调用时配置，numBlocks数量可以通过<a href="./GetBlockNum.html">GetBlockNum</a>获取。</li><li>同时启动AIC和AIV的场景，在AIV、AIC上调用GetBlockIdx的取值范围不同： <ul><li>当AIC和AIV比例为1:2时，AIC上取值范围为[0, numBlocks)，AIV上取值范围为[0, 2 * numBlocks)；</li><li>当AIC和AIV比例为1:1时，AIC上取值范围为[0, numBlocks)，AIV上取值范围为[0, numBlocks)。</li><li>分离模式下，可以通过<a href="./../工具函数/GetTaskRatio.html">GetTaskRatio</a>获取AI Core上AIC与AIV的比例。</li></ul></li></ul><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>GetBlockIdx为一个系统内置函数，返回当前核的index。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// srcGm、dstGm为外部输入的gm空间</span></span>
<span class="line"><span>AscendC::GlobalTensor&lt;float&gt; srcGlobal;</span></span>
<span class="line"><span>AscendC::GlobalTensor&lt;float&gt; dstGlobal;</span></span>
<span class="line"><span>blockNum = AscendC::GetBlockNum(); // 获取核总数</span></span>
<span class="line"><span>perBlockSize = srcDataSize / blockNum; // 每个核平分处理相同个数</span></span>
<span class="line"><span>blockIdx = AscendC::GetBlockIdx(); // 获取当前工作的核ID</span></span>
<span class="line"><span>srcGlobal.SetGlobalBuffer(reinterpret_cast&lt;__gm__ float*&gt;(srcGm + blockIdx * perBlockSize * sizeof(float)), perBlockSize);    // 分配每个核上的srcGlobal的内存地址</span></span>
<span class="line"><span>dstGlobal.SetGlobalBuffer(reinterpret_cast&lt;__gm__ float*&gt;(dstGm + blockIdx * perBlockSize * sizeof(float)), perBlockSize);    // 分配每个核上的dstGlobal的内存地址</span></span></code></pre></div>`,15)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
